"""Port of wpilibjExamples examples/hatchbotcmdv3 (TimedRobot + Commands v3)."""

import telemetry
import tunables
import wpilib

from commands3.button import CommandGamepad
from commands3.custom.greenlets_noco import Command, Scheduler

import autos
from constants import OIConstants
from mechanisms.drive import DriveMechanism
from mechanisms.hatch import HatchMechanism


class Robot(wpilib.TimedRobot):
    def __init__(self):
        super().__init__()
        self.autonomous_chooser = tunables.Selectable()
        self.driver_controller = CommandGamepad(OIConstants.DRIVER_CONTROLLER_PORT)
        self.robot_drive = DriveMechanism()
        self.hatch_mechanism = HatchMechanism()

        self.configure_button_bindings()
        self.robot_drive.set_default_command(self.robot_drive.arcade_drive(
            lambda: -self.driver_controller.get_left_y(),
            lambda: -self.driver_controller.get_right_x()))
        self.hatch_mechanism.set_default_command(self.hatch_mechanism.idle())

        self.autonomous_chooser.add_default("Simple Auto", autos.simple_auto(self.robot_drive))
        self.autonomous_chooser.add("Complex Auto",
                                    autos.complex_auto(self.robot_drive, self.hatch_mechanism))
        tunables.publish("Autonomous", self.autonomous_chooser)

    def configure_button_bindings(self):
        c = self.driver_controller
        c.face_right().on_true(self.hatch_mechanism.grab_hatch_command())
        c.face_left().on_true(self.hatch_mechanism.release_hatch_command())
        (c.right_bumper()
         .on_true(Command.no_requirements(lambda: self.robot_drive.set_max_output(0.5))
                  .named("Set half speed"))
         .on_false(Command.no_requirements(lambda: self.robot_drive.set_max_output(1))
                   .named("Set full speed")))

    def robot_periodic(self):
        Scheduler.get_default().run()
        telemetry.log("Drivetrain", self.robot_drive)
        telemetry.log("HatchMechanism", self.hatch_mechanism)

    def autonomous_init(self):
        command = self.autonomous_chooser.get_selected()
        if command is not None:
            Scheduler.get_default().schedule(command)

    def utility_init(self):
        Scheduler.get_default().cancel_all()
